draw:
var V = 6.0;
var R1 = p.r1, R2 = 200, R3 = 150, R4 = p.r4, Rg = p.rg;

// node equations at A and B, with the source node at V and ground at 0
var a11 = 1 / R1 + 1 / R2 + 1 / Rg;
var a12 = -1 / Rg;
var a21 = -1 / Rg;
var a22 = 1 / R3 + 1 / R4 + 1 / Rg;
var b1 = V / R1, b2 = V / R3;
var det = a11 * a22 - a12 * a21;
var VA = (b1 * a22 - a12 * b2) / det;
var VB = (a11 * b2 - a21 * b1) / det;
var Ig = (VA - VB) / Rg;

var pad = Math.min(W, H) * 0.14;
var xS = W * 0.16, xM = W * 0.5, xG = W * 0.84;
var yA = H * 0.30, yB = H * 0.70, yMid = H * 0.5;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";
ctx.lineWidth = 2;

function seg(ax, ay, bx, by) {
  ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(bx, by); ctx.stroke();
}

function box(cx, cy, label, col) {
  ctx.fillStyle = C.paper;
  ctx.fillRect(cx - 20, cy - 9, 40, 18);
  ctx.strokeStyle = col; ctx.lineWidth = 2;
  ctx.strokeRect(cx - 20, cy - 9, 40, 18);
  ctx.fillStyle = col;
  ctx.fillText(label, cx, cy + 4);
}

// wires
ctx.strokeStyle = C.rule;
seg(xS, yMid, xS, yA); seg(xS, yA, xM, yA); seg(xM, yA, xG, yA); seg(xG, yA, xG, yMid);
seg(xS, yMid, xS, yB); seg(xS, yB, xM, yB); seg(xM, yB, xG, yB); seg(xG, yB, xG, yMid);
seg(xM, yA, xM, yB);

// components
box((xS + xM) / 2, yA, R1.toFixed(0), C.figure);
box((xM + xG) / 2, yA, R2.toFixed(0), C.figure);
box((xS + xM) / 2, yB, R3.toFixed(0), C.figure);
box((xM + xG) / 2, yB, R4.toFixed(0), C.figure);

// galvanometer in the bridge arm
ctx.fillStyle = C.paper;
ctx.beginPath(); ctx.arc(xM, yMid, 14, 0, Math.PI * 2); ctx.fill();
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath(); ctx.arc(xM, yMid, 14, 0, Math.PI * 2); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("G", xM, yMid + 4);

// node dots and names
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(xM, yA, 4, 0, Math.PI * 2); ctx.fill();
ctx.beginPath(); ctx.arc(xM, yB, 4, 0, Math.PI * 2); ctx.fill();
ctx.fillText("A", xM + 16, yA - 8);
ctx.fillText("B", xM + 16, yB + 18);
ctx.fillText("S  " + V.toFixed(1) + " V", xS, yMid - 22);
ctx.fillText("G  0 V", xG, yMid + 30);
ctx.fillStyle = C.faint;
ctx.fillText("VA = " + VA.toFixed(2) + " V", xM - 52, yA - 22);
ctx.fillText("VB = " + VB.toFixed(2) + " V", xM - 52, yB + 32);

// source terminals
ctx.strokeStyle = C.ink; ctx.lineWidth = 4;
ctx.beginPath(); ctx.moveTo(xS - 9, yMid - 6); ctx.lineTo(xS + 9, yMid - 6); ctx.stroke();
ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(xS - 5, yMid + 4); ctx.lineTo(xS + 5, yMid + 4); ctx.stroke();
ctx.beginPath(); ctx.moveTo(xG - 12, yMid); ctx.lineTo(xG + 12, yMid); ctx.stroke();
ctx.beginPath(); ctx.moveTo(xG - 8, yMid + 5); ctx.lineTo(xG + 8, yMid + 5); ctx.stroke();
ctx.beginPath(); ctx.moveTo(xG - 4, yMid + 10); ctx.lineTo(xG + 4, yMid + 10); ctx.stroke();

// current in the bridge arm, animated dots along A-B
var mag = Math.min(1, Math.abs(Ig) / 0.004);
var dir = Ig >= 0 ? 1 : -1;
var k;
ctx.fillStyle = C.accent;
for (k = 0; k < 5; k++) {
  var s = ((k / 5 + dir * (t * (0.15 + mag)) % 1) + 1) % 1;
  var py = yA + s * (yB - yA);
  if (Math.abs(py - yMid) < 16) continue;
  ctx.beginPath(); ctx.arc(xM, py, 3, 0, Math.PI * 2); ctx.fill();
}

var bal = R1 * R4 - R2 * R3;
out.note = "VA - VB = " + (VA - VB).toFixed(3) + " V,  galvanometer current = " +
  (Ig * 1000).toFixed(3) + " mA.  R1*R4 - R2*R3 = " + bal.toFixed(0) +
  (Math.abs(bal) < 1 ? "  (balanced)" : "");
